/**
 * Exercise library for the "add exercise" picker.
 *
 * AUTO-GENERATED by `scripts/build-exercise-library.mjs` — do not edit by
 * hand. Source: hasaneyldrm/exercises-dataset (Gym Visual artwork), with
 * Persian names composed from a word dictionary.
 */

export interface CatalogExercise {
  /** Dataset id, also the GIF file name. */
  id: string;
  /** Persian display name. */
  name: string;
  /** Original English name, searched as a fallback. */
  english: string;
  /** Muscle group key (`chest`, `back`, …) used by the filter chips. */
  muscleKey: string;
  /** Persian muscle label. */
  muscle: string;
  /** Persian equipment label. */
  equipment: string;
  /** Bundled GIF, e.g. `/gifs/catalog/cat-0314.gif`. */
  gif: string;
}

export interface CatalogMuscle {
  key: string;
  label: string;
}

